// ════════════════════════════════════════════════════════════════
//  Opening Range Breakout Box — port dari MQL5 "XPro by Xander"
//  V3 — V7 Pine-style coordinates: line/label pakai xloc=xloc.bar_time
//       (X = datetime epoch) — waktu sesi langsung jadi koordinat.
//       V6.2 var pattern tetap: ALL vars declared at top level, names ≤ 6 chars
// ════════════════════════════════════════════════════════════════
//  Fixes dari V1:
//   - SEMUA variabel declare di TOP LEVEL dulu (V6.2 pattern),
//     if/for block hanya REASSIGN. Engine app kamu tidak register
//     variabel yang first-declared di dalam gated if-block.
//   - Nama variabel ≤ 6 char (priorDn→priDn, extFound→extFnd,
//     bExtOut→bExtO) — hindari truncation nama di engine.
//   - Tetap pakai at() + islast (engine V6.x feature).
// ════════════════════════════════════════════════════════════════

overlay()

// ────────────────────────────────────────────────────────────────
// INPUTS
// ────────────────────────────────────────────────────────────────
rngMin   = 30            // range length (menit)
extMin   = 240           // levels active after range (menit)
daysBk   = 10            // days of history to draw

s1On     = true
s1Strt   = 600           // London 10:00 → 10*60

s2On     = true
s2Strt   = 990           // New York 16:30 → 16*60+30

s3On     = false
s3Strt   = 120           // Asia 02:00 → 2*60

bufPrc   = 0.0           // buffer breakout (raw price)
shTgt    = true
tgt1     = 1.0
tgt2     = 2.0
shLbl    = true
shArr    = true

// ────────────────────────────────────────────────────────────────
// CONSTANTS
// ────────────────────────────────────────────────────────────────
rngSec   = rngMin * 60
extSec   = extMin * 60
daySec   = 86400

// ────────────────────────────────────────────────────────────────
// PER-BAR CONTEXT
// ────────────────────────────────────────────────────────────────
t        = time
i        = bar_index
dayStr   = floor(t / daySec) * daySec
isClsd   = not islast

lastT    = at(time, i)
cutoff   = floor(lastT / daySec) * daySec - daysBk * daySec

maxBck   = (daySec + rngSec + extSec) / 60
strJ     = i - maxBck
if strJ < 0:
    strJ = 0

// ────────────────────────────────────────────────────────────────
// STATE VARIABLES — ALL declared at TOP LEVEL (V6.2 pattern)
// if/for blocks below only REASSIGN these, never declare new ones.
// ────────────────────────────────────────────────────────────────
rHi      = -999999
rLo      =  999999
hasR     = false
bStrt    = 0
bWin     = 0
bExtO    = 0
extFnd   = false
sStrt    = 0
winEnd   = 0
extEnd   = 0
height   = 0
upLvl    = 0
dnLvl    = 0
bExt     = 0
bExtR    = 0
priUp    = false
priDn    = false
tj       = 0
hj       = 0
lj       = 0
ck       = 0
t1u      = 0.0
t1d      = 0.0
t2u      = 0.0
t2d      = 0.0

// ────────────────────────────────────────────────────────────────
// ══ SESSION 1: LONDON (color=blue) ══
// ────────────────────────────────────────────────────────────────
if s1On and t >= cutoff:
    sStrt = dayStr + s1Strt * 60
    if t < sStrt:
        sStrt = sStrt - daySec
    winEnd = sStrt + rngSec
    extEnd = sStrt + rngSec + extSec

    if t >= sStrt and t < extEnd:
        rHi   = -999999
        rLo   =  999999
        hasR  = false
        bStrt = i
        bWin  = i
        bExtO = i
        extFnd = false
        for j in range(strJ, i + 1):
            tj = at(time, j)
            if tj >= sStrt:
                if tj < winEnd:
                    hj = at(high, j)
                    lj = at(low, j)
                    if not hasR:
                        rHi   = hj
                        rLo   = lj
                        hasR  = true
                        bStrt = j
                    else:
                        if hj > rHi:
                            rHi = hj
                        if lj < rLo:
                            rLo = lj
                    bWin = j
                elif tj < extEnd:
                    if not extFnd:
                        bExtO  = j
                        extFnd = true
                    else:
                        bExtO = j

        if hasR:
            vline(sStrt, color=blue, style=style_dashed, xloc=xloc.bar_time)
            box(bStrt, rHi, bWin + 1, rLo,
                color=blue, fill_color=blue, filled=true)
            if shLbl:
                label(bStrt, 0.0006, "London range",
                      color=blue, size=9, yloc=yloc.abovebar)

            if t >= winEnd:
                height = rHi - rLo
                upLvl  = rHi + bufPrc
                dnLvl  = rLo - bufPrc
                bExt   = extFnd ? bExtO : bWin
                bExtR  = bExt + 1

                line(bWin + 1, upLvl, bExtR, upLvl,
                     xloc=xloc.bar_index, color=blue, style=style_solid)
                line(bWin + 1, dnLvl, bExtR, dnLvl,
                     xloc=xloc.bar_index, color=blue, style=style_solid)
                if shLbl:
                    label(bExtR, 0.0006, "Break high " + upLvl,
                          color=blue, size=9, yloc=yloc.abovebar)
                    label(bExtR, 0.0006, "Break low " + dnLvl,
                          color=blue, size=9, yloc=yloc.belowbar)

                if shTgt and height > 0:
                    if tgt1 > 0:
                        t1u = rHi + tgt1 * height
                        t1d = rLo - tgt1 * height
                        line(bWin + 1, t1u, bExtR, t1u,
                             xloc=xloc.bar_index, color=blue, style=style_dotted)
                        line(bWin + 1, t1d, bExtR, t1d,
                             xloc=xloc.bar_index, color=blue, style=style_dotted)
                        if shLbl:
                            label(bExtR, t1u, "T1 " + tgt1 + "x",
                                  color=blue, size=9)
                            label(bExtR, t1d, "T1 " + tgt1 + "x",
                                  color=blue, size=9)
                    if tgt2 > 0:
                        t2u = rHi + tgt2 * height
                        t2d = rLo - tgt2 * height
                        line(bWin + 1, t2u, bExtR, t2u,
                             xloc=xloc.bar_index, color=blue, style=style_dotted)
                        line(bWin + 1, t2d, bExtR, t2d,
                             xloc=xloc.bar_index, color=blue, style=style_dotted)
                        if shLbl:
                            label(bExtR, t2u, "T2 " + tgt2 + "x",
                                  color=blue, size=9)
                            label(bExtR, t2d, "T2 " + tgt2 + "x",
                                  color=blue, size=9)

                if isClsd:
                    priUp = false
                    priDn = false
                    for k in range(bWin + 1, i):
                        ck = at(close, k)
                        if ck > upLvl:
                            priUp = true
                        if ck < dnLvl:
                            priDn = true
                    if not priUp and close > upLvl:
                        if shArr:
                            arrow(buy, low, color=green, size=10)
                        alert("London range broken UP")
                    if not priDn and close < dnLvl:
                        if shArr:
                            arrow(sell, high, color=red, size=10)
                        alert("London range broken DOWN")

// ────────────────────────────────────────────────────────────────
// ══ SESSION 2: NEW YORK (color=orange) ══
// ────────────────────────────────────────────────────────────────
if s2On and t >= cutoff:
    sStrt = dayStr + s2Strt * 60
    if t < sStrt:
        sStrt = sStrt - daySec
    winEnd = sStrt + rngSec
    extEnd = sStrt + rngSec + extSec

    if t >= sStrt and t < extEnd:
        rHi   = -999999
        rLo   =  999999
        hasR  = false
        bStrt = i
