                    else:
                        if hj > rHi:
                            rHi = hj
                        if lj < rLo:
                            rLo = lj
                    bWin = j
                elif tj < extEnd:
                    if not extFnd:
                        bExtO  = j
                        extFnd = true
                    else:
                        bExtO = j

        if hasR:
            vline(sStrt, color=orange, style=style_dashed, xloc=xloc.bar_time)
            box(bStrt, rHi, bWin + 1, rLo,
                color=orange, fill_color=orange, filled=true)
            if shLbl:
                label(bStrt, 0.0006, "New York range",
                      color=orange, size=9, yloc=yloc.abovebar)

            if t >= winEnd:
                height = rHi - rLo
                upLvl  = rHi + bufPrc
                dnLvl  = rLo - bufPrc
                bExt   = extFnd ? bExtO : bWin
                bExtR  = bExt + 1

                line(bWin + 1, upLvl, bExtR, upLvl,
                     xloc=xloc.bar_index, color=orange, style=style_solid)
                line(bWin + 1, dnLvl, bExtR, dnLvl,
                     xloc=xloc.bar_index, color=orange, style=style_solid)
                if shLbl:
                    label(bExtR, 0.0006, "Break high " + upLvl,
                          color=orange, size=9, yloc=yloc.abovebar)
                    label(bExtR, 0.0006, "Break low " + dnLvl,
                          color=orange, size=9, yloc=yloc.belowbar)

                if shTgt and height > 0:
                    if tgt1 > 0:
                        t1u = rHi + tgt1 * height
                        t1d = rLo - tgt1 * height
                        line(bWin + 1, t1u, bExtR, t1u,
                             xloc=xloc.bar_index, color=orange, style=style_dotted)
                        line(bWin + 1, t1d, bExtR, t1d,
                             xloc=xloc.bar_index, color=orange, style=style_dotted)
                        if shLbl:
                            label(bExtR, t1u, "T1 " + tgt1 + "x",
                                  color=orange, size=9)
                            label(bExtR, t1d, "T1 " + tgt1 + "x",
                                  color=orange, size=9)
                    if tgt2 > 0:
                        t2u = rHi + tgt2 * height
                        t2d = rLo - tgt2 * height
                        line(bWin + 1, t2u, bExtR, t2u,
                             xloc=xloc.bar_index, color=orange, style=style_dotted)
                        line(bWin + 1, t2d, bExtR, t2d,
                             xloc=xloc.bar_index, color=orange, style=style_dotted)
                        if shLbl:
                            label(bExtR, t2u, "T2 " + tgt2 + "x",
                                  color=orange, size=9)
                            label(bExtR, t2d, "T2 " + tgt2 + "x",
                                  color=orange, size=9)

                if isClsd:
                    priUp = false
                    priDn = false
                    for k in range(bWin + 1, i):
                        ck = at(close, k)
                        if ck > upLvl:
                            priUp = true
                        if ck < dnLvl:
                            priDn = true
                    if not priUp and close > upLvl:
                        if shArr:
                            arrow(buy, low, color=green, size=10)
                        alert("New York range broken UP")
                    if not priDn and close < dnLvl:
                        if shArr:
                            arrow(sell, high, color=red, size=10)
                        alert("New York range broken DOWN")

// ────────────────────────────────────────────────────────────────
// ══ SESSION 3: ASIA (color=purple) ══
// ────────────────────────────────────────────────────────────────
if s3On and t >= cutoff:
    sStrt = dayStr + s3Strt * 60
    if t < sStrt:
        sStrt = sStrt - daySec
    winEnd = sStrt + rngSec
    extEnd = sStrt + rngSec + extSec

    if t >= sStrt and t < extEnd:
        rHi   = -999999
        rLo   =  999999
        hasR  = false
        bStrt = i
