                            rHi = hj
                        if lj < rLo:
                            rLo = lj
                    bWin = j
                elif tj < extEnd:
                    if not extFnd:
                        bExtO  = j
                        extFnd = true
                    else:
                        bExtO = j

        if hasR:
            vline(sStrt, color=purple, style=style_dashed, xloc=xloc.bar_time)
            box(bStrt, rHi, bWin + 1, rLo,
                color=purple, fill_color=purple, filled=true)
            if shLbl:
                label(bStrt, 0.0006, "Asia range",
                      color=purple, size=9, yloc=yloc.abovebar)

            if t >= winEnd:
                height = rHi - rLo
                upLvl  = rHi + bufPrc
                dnLvl  = rLo - bufPrc
                bExt   = extFnd ? bExtO : bWin
                bExtR  = bExt + 1

                line(bWin + 1, upLvl, bExtR, upLvl,
                     xloc=xloc.bar_index, color=purple, style=style_solid)
                line(bWin + 1, dnLvl, bExtR, dnLvl,
                     xloc=xloc.bar_index, color=purple, style=style_solid)
                if shLbl:
                    label(bExtR, 0.0006, "Break high " + upLvl,
                          color=purple, size=9, yloc=yloc.abovebar)
                    label(bExtR, 0.0006, "Break low " + dnLvl,
