                        line(bWin + 1, t1d, bExtR, t1d,
                             xloc=xloc.bar_index, color=purple, style=style_dotted)
                        if shLbl:
                            label(bExtR, t1u, "T1 " + tgt1 + "x",
                                  color=purple, size=9)
                            label(bExtR, t1d, "T1 " + tgt1 + "x",
                                  color=purple, size=9)
                    if tgt2 > 0:
                        t2u = rHi + tgt2 * height
                        t2d = rLo - tgt2 * height
                        line(bWin + 1, t2u, bExtR, t2u,
