                        line(bWin + 1, t2d, bExtR, t2d,
                             xloc=xloc.bar_index, color=purple, style=style_dotted)
                        if shLbl:
                            label(bExtR, t2u, "T2 " + tgt2 + "x",
                                  color=purple, size=9)
                            label(bExtR, t2d, "T2 " + tgt2 + "x",
